(()=>{'use strict';const q=s=>document.querySelector(s);
const screens={home:{src:'assets/tangora-home.jpg',title:'Give the business a place of its own.',stage:'01 / WEBSITE EXPERIENCE',text:'We developed a website that brings Tangora’s services, brand and contact options into one experience.',url:'https://www.tangora.com.au/',alt:'Actual Tangora Cleaning Services website homepage'},guide:{src:'assets/tangora-guide.jpg',title:'Give visitors something useful to try.',stage:'02 / INTERACTIVE GUIDE',text:'We added a Smart Cleaning Guide so visitors can explore suitable services before they get in touch.',url:'https://www.tangora.com.au/',alt:'Actual Tangora Smart Cleaning Guide with service options and a live plan preview'},booking:{src:'assets/tangora-booking.jpg',title:'Turn interest into a clear request.',stage:'03 / BOOKING JOURNEY',text:'We built a booking-request journey that collects the details Tangora needs to review and confirm a service.',url:'https://www.tangora.com.au/book-cleaner',alt:'Actual Tangora service booking page'}};
const keys=Object.keys(screens);let selected='home';
function show(key){const p=screens[key];if(!p)return;selected=key;const index=keys.indexOf(key);document.querySelectorAll('[data-screen]').forEach(b=>{const distance=(keys.indexOf(b.dataset.screen)-index+keys.length)%keys.length;b.dataset.depth=distance===0?'front':distance===1?'right':'left';b.setAttribute('aria-pressed',String(distance===0))});document.querySelectorAll('[data-project]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.project===key)));q('#capture-stage').textContent=p.stage;q('#capture-title').textContent=p.title;q('#capture-text').textContent=p.text;q('#project-selected-live').href=p.url;q('#project-position').innerHTML=String(index+1).padStart(2,'0')+' <span>/ 03</span>';q('#enlarge-project').setAttribute('aria-label','Open full view of '+p.alt)}
function move(delta){show(keys[(keys.indexOf(selected)+delta+keys.length)%keys.length])}
function enlarge(){const p=screens[selected];q('#project-large').src=p.src;q('#project-large').alt=p.alt;q('#project-lightbox-title').textContent='TANGORA / '+p.stage.slice(5);q('#project-live').href=p.url;q('#project-lightbox').showModal()}
document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.project)));document.querySelectorAll('[data-screen]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.screen)));q('#project-previous').addEventListener('click',()=>move(-1));q('#project-next').addEventListener('click',()=>move(1));q('#project-deck').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();move(e.key==='ArrowLeft'?-1:1)}});q('#enlarge-project').addEventListener('click',enlarge);show('home');
q('#plan-meeting').addEventListener('click',()=>{q('#blueprint').close();q('#meet').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});q('#begin-scheduling').focus({preventScroll:true})});})();
